import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Last-known prices keep totals available when the internal service cannot be
# resolved.  Unknown SKUs still surface the service error rather than silently
# receiving an invented price.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    total = 0.0
    for sku in skus:
        try:
            price = get_price(sku)
        except urllib.error.URLError:
            # Preserve the original failure for SKUs absent from the fallback.
            if sku not in _FALLBACK_PRICES:
                raise
            price = _FALLBACK_PRICES[sku]
        total += price
    return total
